#[test]
fn review_illegal_ordered_read_preserves_stream() {
    let mut pair = Pair::default();
    let (client, server) = pair.connect();
    let stream = pair.client_streams(client).open(Dir::Uni).unwrap();
    pair.client_send(client, stream).write(b"abcdef").unwrap();
    pair.client_send(client, stream).finish().unwrap();
    pair.drive();
    assert_eq!(pair.server_streams(server).accept(Dir::Uni), Some(stream));
    let chunk = pair.server_recv(server, stream).read(false).unwrap().next(3).unwrap().unwrap();
    assert_eq!(&chunk.bytes[..], b"abc");
    assert!(matches!(pair.server_recv(server, stream).read(true), Err(ReadableError::IllegalOrderedRead)));
    let mut recv = pair.server_recv(server, stream);
    let result = recv.read(false);
    assert!(result.is_ok(), "unordered reading should remain possible: {:?}", result.err());
    let mut chunks = result.unwrap();
    assert_eq!(&chunks.next(usize::MAX).unwrap().unwrap().bytes[..], b"def");
    assert!(chunks.next(usize::MAX).unwrap().is_none());
}

