fn review_disable_server_with_pending_incoming() {
    let mut pair = Pair::default();
    pair.server.handle_incoming = Box::new(|_| IncomingConnectionBehavior::Wait);
    pair.begin_connect(client_config());
    pair.drive_client();
    let retransmitted_initial = pair.server.inbound.front().unwrap().2.clone();
    pair.drive_server();
    assert_eq!(pair.server.waiting_incoming.len(), 1);
    pair.server.set_server_config(None);
    pair.server.endpoint.handle(pair.time, pair.client.addr, None, None, retransmitted_initial, &mut Vec::new());
    for incoming in std::mem::take(&mut pair.server.waiting_incoming) {
        pair.server.ignore(incoming);
    }
}

